<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(403);exit('CLI only');}
require __DIR__.'/bootstrap.php';
$pdo=cc_db();if(!$pdo){fwrite(STDERR,"database unavailable\n");exit(1);}
$pdo->exec("CREATE TABLE IF NOT EXISTS system_data_status (dataset VARCHAR(64) PRIMARY KEY,source_name VARCHAR(160) DEFAULT NULL,source_url TEXT DEFAULT NULL,refresh_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 15,status ENUM('ok','partial','error') NOT NULL DEFAULT 'ok',detail VARCHAR(500) DEFAULT NULL,last_checked_at DATETIME NOT NULL,last_updated_at DATETIME DEFAULT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$pdo->exec("CREATE TABLE IF NOT EXISTS shark_status (region_key VARCHAR(64) PRIMARY KEY,region_name VARCHAR(120) NOT NULL,jurisdiction VARCHAR(40) NOT NULL,source_name VARCHAR(160) NOT NULL,source_url TEXT NOT NULL,status_text VARCHAR(255) NOT NULL,alert_mode ENUM('official_app','lifeguard_official','public_web') NOT NULL,source_reachable TINYINT(1) NOT NULL DEFAULT 0,checked_at DATETIME NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$pdo->exec("CREATE TABLE IF NOT EXISTS shark_alerts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,external_key VARCHAR(190) NOT NULL UNIQUE,region_key VARCHAR(64) NOT NULL,locality VARCHAR(160) DEFAULT NULL,alert_type VARCHAR(80) NOT NULL DEFAULT 'shark_alert',title VARCHAR(220) NOT NULL,detail TEXT NOT NULL,observed_at DATETIME DEFAULT NULL,expires_at DATETIME DEFAULT NULL,source_name VARCHAR(160) NOT NULL,source_url TEXT NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,verified_at DATETIME DEFAULT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_shark_active_region(active,region_key,observed_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
function reachable(string $url): bool{if(!function_exists('curl_init'))return true;$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_TIMEOUT=>10,CURLOPT_USERAGENT=>'Mozilla/5.0 CostaCamsSafety/1.0',CURLOPT_NOBODY=>true]);curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);if(in_array($code,[0,403,405],true)){curl_setopt($ch,CURLOPT_NOBODY,false);curl_setopt($ch,CURLOPT_RANGE,'0-1023');curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);}curl_close($ch);return $code>=200&&$code<400;}
$sources=[
['gold-coast','Gold Coast','QLD','Queensland SharkSmart','https://www.dpi.qld.gov.au/initiatives/sharksmart','Official SharkSmart monitoring. Follow lifeguard closures and beach warnings.','lifeguard_official'],
['tweed-coast','Tweed Coast','NSW','NSW SharkSmart','https://www.sharksmart.nsw.gov.au/sharksmart-app','Official NSW SharkSmart provides real-time alerts through its app.','official_app'],
['byron-shire','Byron Shire','NSW','NSW SharkSmart','https://www.sharksmart.nsw.gov.au/sharksmart-app','Official NSW SharkSmart provides real-time alerts through its app.','official_app']];
$st=$pdo->prepare("INSERT INTO shark_status(region_key,region_name,jurisdiction,source_name,source_url,status_text,alert_mode,source_reachable,checked_at) VALUES(?,?,?,?,?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE region_name=VALUES(region_name),jurisdiction=VALUES(jurisdiction),source_name=VALUES(source_name),source_url=VALUES(source_url),status_text=VALUES(status_text),alert_mode=VALUES(alert_mode),source_reachable=VALUES(source_reachable),checked_at=NOW()");
$ok=0;foreach($sources as $s){$r=reachable($s[4]);if($r)$ok++;$st->execute([$s[0],$s[1],$s[2],$s[3],$s[4],$s[5],$s[6],$r?1:0]);}
$pdo->exec("UPDATE shark_alerts SET active=0 WHERE active=1 AND expires_at IS NOT NULL AND expires_at<NOW()");
$detail="Official safety-source checks completed for ".$ok.'/'.count($sources).' endpoints; alert discovery also runs hourly.';
$q=$pdo->prepare("INSERT INTO system_data_status(dataset,source_name,source_url,refresh_minutes,status,detail,last_checked_at,last_updated_at) VALUES('shark_safety','QLD SharkSmart / NSW SharkSmart','https://www.sharksmart.nsw.gov.au/',5,'ok',?,NOW(),NOW()) ON DUPLICATE KEY UPDATE refresh_minutes=5,status='ok',detail=VALUES(detail),last_checked_at=NOW(),last_updated_at=NOW()");$q->execute([$detail]);
echo "shark_sources_checked=".count($sources)." reachable=$ok\n";
